// TASKS.md parser and renderer (task ledger, BD4, docs/spec/formats.md#task-ledger).
//
// parseTasks(text, { file })          -> ledger
// parseTasksDocument(text, { file })  -> { value: ledger, lines }  (lines: Map<JSON pointer, 1-based line>)
// renderTasks(ledger)                 -> text (canonical form)

export const READ_ONLY_NOTICE =
  '> Generated by yaw from GitHub issues. Read-only: change the issues, not this file.';

const FIELDS = [
  ['brief', 'Brief'],
  ['model', 'Model / effort'],
  ['spec', 'Spec'],
  ['resume', 'Resume point'],
];
const LABEL_TO_KEY = new Map(FIELDS.map(([k, label]) => [label, k]));

// Optional block of working rules for the agent, kept verbatim (#175).
export const RULES_HEADING = '## How to work with this file';
export const EFFORTS = ['low', 'medium', 'high', 'xhigh', 'max'];
const MODEL_LINE = /^ {2}model: (\S(?:.*?\S)?)(?: · effort: (\S+))?$/;

// "sonnet", "medium" -> "sonnet · effort: medium" (the Model / effort field of an active task)
export function modelEffort(model, effort) {
  return effort ? `${model} · effort: ${effort}` : model;
}

export class TasksError extends Error {
  constructor(reason, { file, line } = {}) {
    super(`${file ?? 'TASKS.md'}:${line}: ${reason}`);
    this.name = 'TasksError';
    this.reason = reason;
    this.file = file;
    this.line = line;
  }
}

export function parseTasks(text, options) {
  return parseTasksDocument(text, options).value;
}

export function parseTasksDocument(text, { file } = {}) {
  const lines = String(text).replace(/\r\n?/g, '\n').split('\n');
  const pointers = new Map();
  const fail = (reason, idx) => {
    throw new TasksError(reason, { file, line: idx + 1 });
  };
  const ledger = { readOnly: false, active: [], backlog: [] };
  let section = null;
  let task = null;
  let inJournal = false;
  let sawTitle = false;

  lines.forEach((line, idx) => {
    if (line.trim() === '') {
      inJournal = false;
      return;
    }
    if (!sawTitle) {
      if (line !== '# Tasks') fail('expected "# Tasks" as the first line', idx);
      sawTitle = true;
      pointers.set('', idx + 1);
      return;
    }
    if (line.startsWith('> ')) {
      if (section !== null || ledger.readOnly) fail('the read-only notice belongs directly under "# Tasks"', idx);
      ledger.readOnly = true;
      pointers.set('/readOnly', idx + 1);
      return;
    }
    if (section === 'rules' && !line.startsWith('## ')) {
      if (line.startsWith('#')) fail('a heading inside the rules must start with "## "', idx);
      ledger.rules.push(line);
      return;
    }
    if (line.startsWith('## ')) {
      task = null;
      inJournal = false;
      if (line === RULES_HEADING) {
        if (section !== null) fail(`"${RULES_HEADING}" must come before "## Active"`, idx);
        section = 'rules';
        ledger.rules = [];
        pointers.set('/rules', idx + 1);
      } else if (line === '## Active') {
        if (section !== null && section !== 'rules') fail('"## Active" must be the first section', idx);
        section = 'active';
        pointers.set('/active', idx + 1);
      } else if (line === '## Backlog') {
        if (section !== 'active') fail('"## Backlog" must follow "## Active"', idx);
        section = 'backlog';
        pointers.set('/backlog', idx + 1);
      } else {
        const m = /^## Done → (\S+)$/.exec(line);
        if (!m) fail(`unknown section "${line}"`, idx);
        if (section !== 'backlog') fail('"## Done → <file>" must follow "## Backlog"', idx);
        section = 'done';
        ledger.archive = m[1];
        pointers.set('/archive', idx + 1);
      }
      return;
    }
    if (section === 'active') {
      if (line.startsWith('### ')) {
        const m = /^### (\S+)(?: \(#(\d+)\))? (.+) — ([a-z][a-z ]*?)(?: \((\d+) %\))?$/.exec(line);
        if (!m) fail('expected "### <id> <title> — <status>[ (<n> %)]"', idx);
        task = { id: m[1] };
        if (m[2] !== undefined) task.issue = Number(m[2]);
        task.title = m[3];
        task.status = m[4];
        if (m[5] !== undefined) task.progress = Number(m[5]);
        task.journal = [];
        inJournal = false;
        pointers.set(`/active/${ledger.active.length}`, idx + 1);
        ledger.active.push(task);
        return;
      }
      if (!task) fail('expected a task heading "### <id> <title> — <status>"', idx);
      const base = `/active/${ledger.active.length - 1}`;
      if (inJournal && line.startsWith('  - ')) {
        const m = /^ {2}- (\S+) (.+)$/.exec(line);
        if (!m) fail('expected "  - <YYYY-MM-DD> <text>"', idx);
        pointers.set(`${base}/journal/${task.journal.length}`, idx + 1);
        task.journal.push({ date: m[1], text: m[2] });
        return;
      }
      if (line === '- **Journal:**') {
        if (task.journalSeen) fail('duplicate field "Journal"', idx);
        task.journalSeen = true;
        inJournal = true;
        pointers.set(`${base}/journal`, idx + 1);
        return;
      }
      const f = /^- \*\*(.+?):\*\* (.+)$/.exec(line);
      if (!f) fail(`unexpected line in task ${task.id}`, idx);
      const key = LABEL_TO_KEY.get(f[1]);
      if (!key) fail(`unknown field "${f[1]}" (expected ${FIELDS.map(([, l]) => l).join(', ')}, Journal)`, idx);
      if (Object.prototype.hasOwnProperty.call(task, key)) fail(`duplicate field "${f[1]}"`, idx);
      task[key] = f[2];
      inJournal = false;
      pointers.set(`${base}/${key}`, idx + 1);
      return;
    }
    if (section === 'backlog') {
      if (line.startsWith('  ')) {
        const item = ledger.backlog.at(-1);
        const m = MODEL_LINE.exec(line);
        if (!item || !m) fail('expected "  model: <tier>[ · effort: <level>]" under a backlog line', idx);
        if (item.model !== undefined) fail(`duplicate model line for ${item.id}`, idx);
        if (m[2] !== undefined && !EFFORTS.includes(m[2])) fail(`effort must be one of ${EFFORTS.join(', ')}`, idx);
        item.model = m[1];
        if (m[2] !== undefined) item.effort = m[2];
        pointers.set(`/backlog/${ledger.backlog.length - 1}/model`, idx + 1);
        return;
      }
      const m = /^- (\S+)(?: \(#(\d+)\))? (.+?)(?: — (.+))?$/.exec(line);
      if (!m) fail('expected "- <id> <title>[ — <note>]"', idx);
      const item = { id: m[1] };
      if (m[2] !== undefined) item.issue = Number(m[2]);
      item.title = m[3];
      if (m[4] !== undefined) item.note = m[4];
      pointers.set(`/backlog/${ledger.backlog.length}`, idx + 1);
      ledger.backlog.push(item);
      return;
    }
    fail(section === 'done' ? 'nothing may follow "## Done → <file>"' : 'expected "## Active"', idx);
  });

  if (!sawTitle) fail('expected "# Tasks" as the first line', 0);
  const last = lines.findLastIndex((l) => l.trim() !== '');
  if (section === null || section === 'rules') fail('missing "## Active" section', last);
  if (ledger.rules?.length === 0) fail('the rules section is empty', lines.findIndex((l) => l === RULES_HEADING));
  if (section === 'active') fail('missing "## Backlog" section', last);
  for (const t of ledger.active) {
    if (!t.journalSeen) delete t.journal;
    delete t.journalSeen;
    // Keep a stable key order: id, issue, title, status, progress, fields, journal.
    const journal = t.journal;
    delete t.journal;
    if (journal) t.journal = journal;
  }
  return { value: ledger, lines: pointers };
}

export function renderTasks(ledger) {
  const out = ['# Tasks', ''];
  if (ledger.readOnly) out.push(READ_ONLY_NOTICE, '');
  if (ledger.rules?.length) out.push(RULES_HEADING, '', ...ledger.rules, '');
  out.push('## Active');
  for (const t of ledger.active) {
    const issue = t.issue !== undefined ? ` (#${t.issue})` : '';
    const progress = t.progress !== undefined ? ` (${t.progress} %)` : '';
    out.push(`### ${t.id}${issue} ${t.title} — ${t.status}${progress}`);
    for (const [key, label] of FIELDS) {
      if (t[key] !== undefined) out.push(`- **${label}:** ${t[key]}`);
    }
    if (t.journal) {
      out.push('- **Journal:**');
      for (const j of t.journal) out.push(`  - ${j.date} ${j.text}`);
    }
    out.push('');
  }
  if (ledger.active.length === 0) out.push('');
  out.push('## Backlog');
  for (const b of ledger.backlog) {
    const issue = b.issue !== undefined ? ` (#${b.issue})` : '';
    const note = b.note !== undefined ? ` — ${b.note}` : '';
    out.push(`- ${b.id}${issue} ${b.title}${note}`);
    if (b.model !== undefined) out.push(`  model: ${modelEffort(b.model, b.effort)}`);
  }
  if (ledger.archive !== undefined) out.push('', `## Done → ${ledger.archive}`);
  return `${out.join('\n')}\n`;
}

// Without GitHub tasks stay local, including teams using a local Git remote.
export const TASK_MODES = ['local', 'github', 'both'];

export function tasksMode(answers = {}, { teamModule = false } = {}) {
  if (teamModule) return 'github';
  if (answers['tasks.use-github'] === false) return 'local';
  if ((answers['idea.team'] ?? 'solo') !== 'solo') return 'github';
  const mode = answers['tasks.mode'];
  return TASK_MODES.includes(mode) ? mode : 'local';
}
